// ===== CONFIGURACIÓN DE SUPABASE (valores PÚBLICOS: los mismos de envios.js) =====
const SUPABASE_URL = 'https://lcaqniptbppilsiopvgd.supabase.co';             // ej. https://abcdefgh.supabase.co
const SUPABASE_ANON_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImxjYXFuaXB0YnBwaWxzaW9wdmdkIiwicm9sZSI6ImFub24iLCJpYXQiOjE3OTI5NTk3MTIsImV4cCI6MjEwODUzNTcxMn0.cBgkWvP6_e0bhSkTjFvZp5eqnoQ4PNEUqlxTtnGqGmo';   // clave "anon public"
// ================================================================================
const inp = $input.first().json;
const b = inp.body || {};
const wurl = String(inp.webhookUrl || '');
const route = wurl.endsWith('gbforce-envios-lista') ? 'lista' : (wurl.endsWith('gbforce-envios-ingreso') ? 'ingreso' : 'marcar');
const h = inp.headers || {};
const ip = String(h['cf-connecting-ip'] || h['x-real-ip'] || String(h['x-forwarded-for'] || '').split(',')[0] || '').trim();
const token = (typeof b.token === 'string' && /^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(b.token)) ? b.token : '';
return [{ json: { route, token, body: b, ip, supaUrl: SUPABASE_URL.replace(/\/$/, ''), anon: SUPABASE_ANON_KEY } }];

// ===== CORREOS AUTORIZADOS (opcional pero recomendado: segunda barrera) =====
const CORREOS_AUTORIZADOS = '';   // ej. 'ana@gbforce.mx, luis@gbforce.mx'  (vacío = cualquier usuario creado por ti en Supabase)
// =========================================================================
const prep = $('Preparar token').item.json;
const u = $('Supabase: validar sesión').item.json || {};

// Ajustes editables en Airtable (tabla "Configuración"). Si no se pueden leer, se usan estos valores
let INACT = 8, MAXH = 24;
try {
  const recs = ($input.first().json.records) || [];
  for (const r of recs) {
    const f = r.fields || {};
    const v = parseFloat(String(f['Valor']).replace(',', '.'));
    if (!isFinite(v)) continue;
    if (f['Clave'] === 'envios_inactividad_horas') INACT = Math.min(72, Math.max(0.25, v));
    if (f['Clave'] === 'envios_sesion_maxima_horas') MAXH = Math.min(168, Math.max(1, v));
  }
} catch (e) {}
const cfg = { inactividadHoras: INACT, maximaHoras: MAXH };

const fail = (reason) => [{ json: { ok: false, reason, route: prep.route } }];
if (!prep.token || !u.id || !u.email) return fail('token_invalido');
let p;
try {
  const part = prep.token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
  p = JSON.parse(Buffer.from(part, 'base64').toString('utf8'));
} catch (e) { return fail('token_ilegible'); }
if (p.sub !== u.id) return fail('usuario_distinto');
if (!p.exp || p.exp * 1000 < Date.now()) return fail('expirado');
if (p.aal !== 'aal2') return fail('sin_segundo_paso');           // exige verificación en dos pasos

// Duración máxima de la sesión, contada desde el último código de Google Authenticator
// (la fecha viaja firmada dentro del token, no se puede falsificar desde el navegador)
const amr = Array.isArray(p.amr) ? p.amr : [];
const totp = amr.filter(a => a && a.method === 'totp').map(a => Number(a.timestamp) || 0);
if (!totp.length) return fail('sin_registro_segundo_paso');
if (Date.now() / 1000 - Math.max.apply(null, totp) > MAXH * 3600) return fail('sesion_maxima');

const email = String(u.email).toLowerCase();
const lista = CORREOS_AUTORIZADOS.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
if (lista.length && !lista.includes(email)) return fail('no_autorizado');
return [{ json: { ok: true, email, route: prep.route, body: prep.body, ip: prep.ip, cfg } }];

const s = $('Validar sesión').item.json;
const vista = s.body && s.body.vista === 'enviados' ? 'enviados' : 'por-enviar';
const formula = vista === 'enviados'
  ? 'AND({Estado}="PAGADO",{Logística}="ENVIADO",IS_AFTER({EnviadoEn},DATEADD(NOW(),-14,"days")))'
  : 'AND({Estado}="PAGADO",{Logística}="POR ENVIAR")';
return [{ json: { formula, dir: vista === 'enviados' ? 'desc' : 'asc', campo: vista === 'enviados' ? 'EnviadoEn' : 'PagadoEn' } }];

const recs = ($input.first().json.records) || [];
const pedidos = recs.map(r => { const f = r.fields || {}; return {
  pedido: f['Pedido'] || '', nombre: f['Nombre'] || '', telefono: f['Teléfono'] || '',
  calle: f['Calle'] || '', colonia: f['Colonia'] || '', cp: f['CP'] || '', ciudad: f['Ciudad'] || '',
  estado: f['Estado de envío'] || '', referencias: f['Referencias'] || '', cantidad: Number(f['Cantidad']) || 1,
  pagadoEn: f['PagadoEn'] || '', paqueteria: f['Paquetería'] || '', guia: f['Guía'] || '', enviadoEn: f['EnviadoEn'] || ''
}; });
const cfg = $('Validar sesión').item.json.cfg || {};
// Solo datos de envío y cantidad: sin montos, sin datos de pago, sin correo.
// "config" le dice a la página cuántas horas de inactividad tolerar (se cambia en Airtable > Configuración)
return [{ json: { pedidos, totalPedidos: pedidos.length, totalCajas: pedidos.reduce((s, p) => s + p.cantidad, 0), config: { inactividadHoras: cfg.inactividadHoras || 8, maximaHoras: cfg.maximaHoras || 24 } } }];

const s = $('Validar sesión').item.json;
const b = s.body || {};
const clean = (x, max) => String(x == null ? '' : x).replace(/[\u0000-\u001f<>]/g, ' ').trim().slice(0, max);
const pedido = String(b.pedido || '');
if (!/^GB-[A-Z0-9]{6}$/.test(pedido)) return [{ json: { ok: false, error: 'pedido_invalido' } }];
const accion = b.accion === 'deshacer' ? 'deshacer' : 'enviar';
const paqueteria = clean(b.paqueteria, 40), guia = clean(b.guia, 60);
if (accion === 'enviar' && (!paqueteria || !guia)) return [{ json: { ok: false, error: 'faltan_datos' } }];
return [{ json: { ok: true, formula: '{Pedido}="' + pedido + '"', accion, paqueteria, guia } }];

const v = $('Validar marcar').item.json;
const recs = ($input.first().json.records) || [];
if (!recs.length || (recs[0].fields || {})['Estado'] !== 'PAGADO') return [{ json: { ok: false, error: 'pedido_no_pagado_o_inexistente' } }];
const f = recs[0].fields;
const fields = v.accion === 'enviar'
  ? { 'Logística': 'ENVIADO', 'Paquetería': v.paqueteria, 'Guía': v.guia, 'EnviadoEn': new Date().toISOString() }
  : { 'Logística': 'POR ENVIAR', 'Paquetería': '', 'Guía': '', 'EnviadoEn': null };
return [{ json: { ok: true, recordId: recs[0].id, fields, accion: v.accion, pedido: f['Pedido'], correo: f['Correo'] || '', nombre: f['Nombre'] || '', paqueteria: v.paqueteria, guia: v.guia } }];

const s = $('Validar sesión').item.json;
const p = $('Preparar cambio').item.json;
const enviar = p.accion === 'enviar';
const accion = enviar ? 'MARCAR ENVIADO' : 'DESHACER ENVÍO';
const detalle = enviar ? ('Paquetería: ' + p.paqueteria + ' · Guía: ' + p.guia) : 'Regresado a Por enviar';
return [{ json: { registro: { typecast: true, records: [ { fields: { 'Resumen': s.email + ' · ' + accion + ' · ' + p.pedido, 'Fecha': new Date().toISOString(), 'Usuario': s.email, 'Acción': accion, 'Pedido': p.pedido, 'IP': s.ip, 'Detalle': detalle } } ] } } }];

const FROM_EMAIL = 'admin@gbforce.mx';   // el mismo remitente de los otros correos
const p = $('Preparar cambio').item.json;
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const html = '<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;color:#222">'
  + '<h2 style="margin:0 0 8px">¡Tu pedido va en camino!</h2>'
  + '<p>Hola ' + esc(String(p.nombre).split(' ')[0]) + ', ya enviamos tu pedido <b>' + esc(p.pedido) + '</b>.</p>'
  + '<p><b>Paquetería:</b> ' + esc(p.paqueteria) + '<br><b>Número de guía:</b> ' + esc(p.guia) + '</p>'
  + '<p>Con ese número puedes seguir tu envío en el sitio de la paquetería.</p>'
  + '<p style="color:#777;font-size:13px">¿Dudas? Llámanos al +52 33 3172 1515 o escribe a contacto@gbforce.mx.</p></div>';
return [{ json: { skip: p.accion !== 'enviar' || !p.correo, fromEmail: FROM_EMAIL, to: p.correo, subject: 'Tu pedido ' + p.pedido + ' va en camino', html } }];
